  ('qa2-f7b37c197ef4309948a91508', '10007161', 'ISM7: RESOURCE - Counselling Call-out Contract', 'New Initiative', 'To establish a call-out contract with an external supplier of therapeutic interventions to outsource counselling waiting list students.', '["2 Mental Health Success -To remove the gaps in continuation, completion, and attainment for students with diagnosed mental health conditions when compared to TU students with no known disability by 2029."]'::jsonb, 'Students with diagnosed mental health conditions', '["disability"]'::jsonb, '["continuation", "completion", "attainment"]'::jsonb, '["PTS_1", "PTS_2", "PTS_3"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 8 – Mental health"]'::jsonb, 13, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-c3e4ab56ca8e2c61a3d90b4c', '10007161', 'ISM8: INTEGRATION - Residential Transitions Events', NULL, 'Residential stay on campus for 30 applicants with mental health conditions and/or autism diagnoses.', '["2 Mental Health Success -To remove the gaps in continuation, completion, and attainment for students with diagnosed mental health conditions when compared to TU students with no known disability by 2029.", "3 Social and Communication Disabilities Continuation - To significantly reduce the gap in continuation rates between students with social and communication disabilities when compared to TU students with no known disability by 2029."]'::jsonb, 'Applicants with mental health conditions and/or autism diagnoses', '["disability"]'::jsonb, '["continuation"]'::jsonb, '["PTS_1", "PTS_4", "PTS_2", "PTS_3"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 8 – Mental health"]'::jsonb, 13, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-838420783b3b6a59ff7f3897', '10007161', 'ISM9: CULTURE - Staff Training / Skills Development', NULL, 'Online training module development aimed at raising confidence levels of all staff when interacting with students with existing and potential mental health conditions.', '["2 Mental Health Success -To remove the gaps in continuation, completion, and attainment for students with diagnosed mental health conditions when compared to TU students with no known disability by 2029.", "3 Social and Communication Disabilities Continuation - To significantly reduce the gap in continuation rates between students with social and communication disabilities when compared to TU students with no known disability by 2029.", "4 Cognitive and Learning Disabilities Attainment - To significantly reduce the gap in attainment rates between students with cognitive and learning disabilities when compared to TU students with no known disability by 2029."]'::jsonb, 'Staff interacting with students with learning, cognitive or social & communication conditions', '["disability"]'::jsonb, '["continuation", "completion", "attainment"]'::jsonb, '["PTS_1", "PTS_2", "PTS_3", "PTS_4", "PTS_5"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 8 – Mental health", "EORR Risk 11 – Capacity issues"]'::jsonb, 13, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-7e5f250ee52677f1cc8a58f3', '10007161', 'IST1: TEES VALLEY PROGRESS PROJECT - Mentoring Scheme', NULL, 'Following the success of the recent Advantage Tees Valley Mentoring programme where over 60 students were matched with mentors across the Tees Valley, we want to further build on this with the launch of an APP focussed programme.', '["5 TUNDRA Q1&2 Progression - To significantly reduce the gap in progression rates for graduates from TUNDRA Q1 and to remove the gap in progression rates for graduates from a Q2 background as compared to TU graduates from TUNDRA Q5 by 2032.", "6 Mental Health Progression - to significantly reduce the gap in progression rates for graduates with a diagnosed mental health condition when compared to students with no known disability by 2032."]'::jsonb, 'APP target graduates from Tees Valley', '["area_based"]'::jsonb, '["progression"]'::jsonb, '["PTP_1", "PTP_2", "PTP_3"]'::jsonb, '["EORR Risk 7 – Insufficient personal support", "EORR Risk 12 – Progression from higher education"]'::jsonb, 20, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-0a94a1993b8651d46b920f52', '10007161', 'IST2: TEES VALLEY PROGRESS PROJECT - Funded 3- and 6-month graduate internships', NULL, 'Funded 3- and 6-month graduate internships with SMEs within the Tees Valley. The ERDF funded Graduates for Growth programme is about to end. This programme has fully funded or part-funded 3- and 6-month internships with 144 companies within the Tees Valley over 5 years. This activity would extend this Graduates for Growth programme at TU.', '["5 TUNDRA Q1&2 Progression - To significantly reduce the gap in progression rates for graduates from TUNDRA Q1 and to remove the gap in progression rates for graduates from a Q2 background as compared to TU graduates from TUNDRA Q5 by 2032.", "6 Mental Health Progression - to significantly reduce the gap in progression rates for graduates with a diagnosed mental health condition when compared to students with no known disability by 2032."]'::jsonb, 'Graduates from Tees Valley', '["area_based"]'::jsonb, '["progression"]'::jsonb, '["PTP_1", "PTP_2", "PTP_3"]'::jsonb, '["EORR Risk 7 – Insufficient personal support", "EORR Risk 12 – Progression from higher education"]'::jsonb, 21, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-f389f22faebd54dbfdfc15a8', '10007161', 'IST3: TEES VALLEY PROGRESS PROJECT – Tutors and Coaches', NULL, 'Establish a dedicated graduate-focussed team offering a continuation of employability support past graduation. Support would include weekly check-ins giving employability guidance, pastoral care, and recruitment support.
Graduate Coaches offer an extension to TU’s academic and progression support and sit within an APP-aligned programme of targeted support for APP groups which run from Level 4 to Level 6 into the first 12 months of graduate status.', '["5 TUNDRA Q1&2 Progression - To significantly reduce the gap in progression rates for graduates from TUNDRA Q1 and to remove the gap in progression rates for graduates from a Q2 background as compared to TU graduates from TUNDRA Q5 by 2032.", "6 Mental Health Progression - to significantly reduce the gap in progression rates for graduates with a diagnosed mental health condition when compared to students with no known disability by 2032."]'::jsonb, 'APP target graduates requiring additional support', '["area_based"]'::jsonb, '["progression"]'::jsonb, '["PTP_1", "PTP_2", "PTP_3"]'::jsonb, '["EORR Risk 7 – Insufficient personal support", "EORR Risk 12 – Progression from higher education"]'::jsonb, 21, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-8f3042ba40608a96f9bfb4a3', '10007161', 'IST4: GRADUATE OPPORTUNITIES - Summer Internships', NULL, 'An ongoing initiative that creates around 90 funded internships per year for recent graduates. Graduates are employed by the university but placed within organisations.', '["5 TUNDRA Q1&2 Progression - To significantly reduce the gap in progression rates for graduates from TUNDRA Q1 and to remove the gap in progression rates for graduates from a Q2 background as compared to TU graduates from TUNDRA Q5 by 2032.", "6 Mental Health Progression - to significantly reduce the gap in progression rates for graduates with a diagnosed mental health condition when compared to students with no known disability by 2032."]'::jsonb, 'Recent graduates', '["area_based"]'::jsonb, '["progression"]'::jsonb, '["PTP_1", "PTP_2", "PTP_3"]'::jsonb, '["EORR Risk 7 – Insufficient personal support", "EORR Risk 12 – Progression from higher education"]'::jsonb, 21, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-6440b15a8cdbcdd5f02ed175', '10007161', 'IST5: STUDENT OPPORTUNITIES - Student transition to Employment Initiative', NULL, 'This initiative creates support for students in finding and applying for part-time/degree related/on campus vacancies that they can hold alongside their studies.', '["5 TUNDRA Q1&2 Progression - To significantly reduce the gap in progression rates for graduates from TUNDRA Q1 and to remove the gap in progression rates for graduates from a Q2 background as compared to TU graduates from TUNDRA Q5 by 2032.", "6 Mental Health Progression - to significantly reduce the gap in progression rates for graduates with a diagnosed mental health condition when compared to students with no known disability by 2032."]'::jsonb, 'Undergraduate students', '["area_based"]'::jsonb, '["progression"]'::jsonb, '["PTP_1", "PTP_2", "PTP_3"]'::jsonb, '["EORR Risk 7 – Insufficient personal support", "EORR Risk 12 – Progression from higher education"]'::jsonb, 22, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-b1b4f44f9b2366cc2d3ff63c', '10007161', 'IST6: GRADUATE SUPPORT - Extended Mental Health Support', NULL, 'Extend mental health support to students beyond graduation.', '["5 TUNDRA Q1&2 Progression - To significantly reduce the gap in progression rates for graduates from TUNDRA Q1 and to remove the gap in progression rates for graduates from a Q2 background as compared to TU graduates from TUNDRA Q5 by 2032.", "6 Mental Health Progression - to significantly reduce the gap in progression rates for graduates with a diagnosed mental health condition when compared to students with no known disability by 2032."]'::jsonb, 'Graduates with diagnosed mental health conditions', '["disability"]'::jsonb, '["progression"]'::jsonb, '["PTP_1", "PTP_2", "PTP_3"]'::jsonb, '["EORR Risk 7 – Insufficient personal support", "EORR Risk 8 – Mental health", "EORR Risk 12 – Progression from higher education"]'::jsonb, 22, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-cf2e9efcc5407296be4f49a1', '10007161', 'IST7: GRADUATE SUPPORT - Extended Adobe access', NULL, 'Extension of access to Adobe packages 18 months after graduation, for target students. Students can access the extensive Adobe packages whilst they are studying. Having an extended period of access would allow the now graduate to be able to tailor their work and applications to vacancies.', '["5 TUNDRA Q1&2 Progression - To significantly reduce the gap in progression rates for graduates from TUNDRA Q1 and to remove the gap in progression rates for graduates from a Q2 background as compared to TU graduates from TUNDRA Q5 by 2032.", "6 Mental Health Progression - to significantly reduce the gap in progression rates for graduates with a diagnosed mental health condition when compared to students with no known disability by 2032."]'::jsonb, 'Graduates with diagnosed mental health conditions', '["disability"]'::jsonb, '["progression"]'::jsonb, '["PTP_1", "PTP_2", "PTP_3"]'::jsonb, '["EORR Risk 7 – Insufficient personal support", "EORR Risk 8 – Mental health", "EORR Risk 12 – Progression from higher education"]'::jsonb, 22, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-5cc3f804431c7efda3bcf46b', '10007161', 'ISR1: SMALL SAMPLE PILOT - Year 9/10 Project', NULL, 'Target 40 pupils from a WP cohort (20 Year 9/20 Year 10) from key feeder schools/academies. Pupils are required to commit to scheme throughout 2-year period. Year 9 programme develops understanding of HE through a series of four interactive IAG workshops delivered in School. Pupils are then invited to Choose your future event. Year 10 programme links schools, HE, and businesses through five workshops and site visits. Workshops include a STEM Day and Creative Day as well as visits to local employers. Following visits pupils take part in a project based on that visit.', '["7 Pre-16 Attainment - To improve the regional opportunities for pre-16 students to attend HE by 2028 and to reduce the gap in attainment rates in the North East region when compared to the national average. To increase year on year the number of school staff in the Tees Valley undertaking a TU led digital upskilling programme."]'::jsonb, 'Year 9 and 10 pupils from WP cohort', '["age", "fsm", "region"]'::jsonb, '["pre_entry_attainment"]'::jsonb, '["PTA_2"]'::jsonb, '["EORR Risk 1 – Knowledge and skills", "EORR Risk 2 – Information and guidance", "EORR Risk 3 – Perception of higher education", "EORR Risk 4 – Application success rates"]'::jsonb, 24, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-2f37039e7f9115ac529595a7', '10007161', 'ISR2: ONE-DAY EVENTS Choose Your Future (Year 9)', NULL, 'One day event providing information on HE, choice of academic workshops, overview of student experience.', '["7 Pre-16 Attainment - To improve the regional opportunities for pre-16 students to attend HE by 2028 and to reduce the gap in attainment rates in the North East region when compared to the national average. To increase year on year the number of school staff in the Tees Valley undertaking a TU led digital upskilling programme."]'::jsonb, 'Year 9 pupils', '["age", "region"]'::jsonb, '["pre_entry_attainment"]'::jsonb, '["PTA_2"]'::jsonb, '["EORR Risk 1 – Knowledge and skills", "EORR Risk 2 – Information and guidance", "EORR Risk 3 – Perception of higher education", "EORR Risk 4 – Application success rates"]'::jsonb, 24, 'Checked by the automated reviewer; corrections not yet applied'),
