  ('qa2-7b0b0e75033fe27342666f98', '10004344', 'Academic Preparedness – Transition Programme', 'New initiative', 'Tailored transition programme to enhance academic confidence and preparedness for the next academic study level.
The target group will be students identified as from TUNDRA Quintile 1 and Quintile 2.

This will be a new activity delivered in collaboration with the College’s wider Careers Team and Department Academic Staff and the Student Support and Participation Coordinator.', '["1.1 Increasing Continuation Rates for Students in TUNDRA Quintile 1 and 2"]'::jsonb, 'students identified as from TUNDRA Quintile 1 and Quintile 2', '["area_based"]'::jsonb, '["continuation"]'::jsonb, '["PTS_1", "PTS_2"]'::jsonb, '["EORR Risk 1 – Knowledge and skills", "EORR Risk 2 – Information and guidance", "EORR Risk 7 – Insufficient personal support", "EORR Risk 10 – Cost pressures"]'::jsonb, 8, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-9158b4f283450cb2e9e796fa', '10004344', 'Inclusive Careers Coaching', 'New initiative', 'A series of workshops for students with disabilities providing tailored careers advice tailored to individual needs, taking into account the diverse range of disabilities and the unique barriers students may face in planning and pursuing their career goals.

The target group will be students who have identified that they have a disability at point of enrolment or at any point during their time on their programme of study.

This will be a new activity delivered in collaboration with external employability services, the College’s Student Service, Careers, and Wellbeing Team.', '["2.1 Reducing the Progression Gap for Disabled Students"]'::jsonb, 'students who have identified that they have a disability at point of enrolment or at any point during their time on their programme of study', '["disability"]'::jsonb, '["progression"]'::jsonb, '["PTP_1"]'::jsonb, '["EORR Risk 2 – Information and guidance", "EORR Risk 12 – Progression from higher education"]'::jsonb, 12, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-ff26f1359b7f5ca03f463600', '10004344', 'Transition Pathways Programme', 'New initiative', 'This is a structured, personalised programme for students entering their final year of study (final year of a Foundation Degree or final year of BA/BSc). The programme will offer tailored guidance, practical resources, and facilitated connections with inclusive employers. It will include career planning workshops, mock interviews, workplace visits, and mentoring opportunities.
The target group will be students who have identified that they have a disability at point of enrolment or at any point during their time on their programme of study.

This will be a new activity delivered in collaboration with external employability services, the College’s Student Services, Careers and Wellbeing Team.', '["2.1 Reducing the Progression Gap for Disabled Students"]'::jsonb, 'students who have identified that they have a disability at point of enrolment or at any point during their time on their programme of study', '["disability"]'::jsonb, '["progression"]'::jsonb, '["PTP_1"]'::jsonb, '["EORR Risk 2 – Information and guidance", "EORR Risk 12 – Progression from higher education"]'::jsonb, 13, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-527b856f5f1935827d182c33', '10004344', 'Employer Accessibility Partnership', 'New initiative', 'This activity will develop a partnership programme with local and national employers to improve workplace accessibility and perception to promote inclusive recruitment practices for disabled students. This initiative will also facilitate direct engagement between employers and disabled students through inclusive careers fairs, networking events, and work-based learning opportunities. Fostering a mutual understanding and collaboration aims to challenge misconceptions about disability in the workplace and build a network of employers committed to inclusive hiring practices for disabled students.
Students will be provided with greater visibility of accessible career pathways and increase their confidence in navigating the job market.
The target group will be students who have identified that they have a disability at point of enrolment or at any point during their time on their programme of study.

This will be a new activity delivered in collaboration with the College’s wider Careers Team, Department Academic Staff, the Student Support and Participation Coordinator and external employers.', '["2.1 Reducing the Progression Gap for Disabled Students"]'::jsonb, 'students who have identified that they have a disability at point of enrolment or at any point during their time on their programme of study', '["disability"]'::jsonb, '["progression"]'::jsonb, '["PTP_1"]'::jsonb, '["EORR Risk 2 – Information and guidance", "EORR Risk 12 – Progression from higher education"]'::jsonb, 14, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-1a63a17b0334672270e8b3b0', '10004344', 'Peer Mentoring and Role Model Network', 'New initiative', 'This activity will establish a structured peer mentoring programme aimed at supporting white males from IMD Q1 and Q2. The aim will be to connect these students with relatable role models (including current students and alumni from similar backgrounds). Mentoring relationships will be built around shared experiences, fostering trust, motivation, and a sense of belonging.
The target group will be young white males from IMD Q1 and Q2.

This will be a new activity delivered in collaboration with alumni, the College’s Student Service, and Wellbeing Team.', '["3.1 Improve Continuation Rates for Young White Males from IMD Q1 and Q2"]'::jsonb, 'young white males from IMD Q1 and Q2', '["age", "ethnicity", "sex", "area_based"]'::jsonb, '["continuation"]'::jsonb, '["PTS_2", "PTS_1"]'::jsonb, '["EORR Risk 7 – Insufficient personal support", "EORR Risk 10 – Cost pressures"]'::jsonb, 20, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-cf9059240acf41bb87ae481b', '10004344', 'Personalised Retention Support', NULL, 'This activity expands the College’s existing retention support by introducing a more targeted and proactive approach for students being at risk of withdrawal – particularly young white males from IMD Q1 and Q2. Using predictive analytics and early warning indicators (attendance, engagement, extenuating circumstance applications), students will be identified form personalised interventions with the Student Support and Participation Coordinator. The Student Support and Participation Coordinator will coordinate regular check-ins, academic support, and referrals to wider wellbeing services, if required.
The target group will be young white males from IMD Q1 and Q2.

This in an existing activity which will be expanded to employ a more targeted and proactive approach. This activity will be delivered in collaboration with the Student Support and Participation Coordinator, the College’s Student Services, and Wellbeing Team.', '["3.1 Improve Continuation Rates for Young White Males from IMD Q1 and Q2"]'::jsonb, 'young white males from IMD Q1 and Q2', '["age", "ethnicity", "sex", "area_based"]'::jsonb, '["continuation"]'::jsonb, '["PTS_2", "PTS_1"]'::jsonb, '["EORR Risk 7 – Insufficient personal support", "EORR Risk 10 – Cost pressures"]'::jsonb, 21, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-9eb0692d6133b4a0f1243840', '10004599', 'Student Support and Development', NULL, 'Provide bespoke support workshops and online training packages for target students from level 3, in the following areas: Academic skills. New activity. English for Academic Purposes (EAP) for HE students where English as a second or other language. New activity. Digital literacy skills to support studies and accessing resources. New Activity. All students within the ‘Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage’ target groups will be offered the academic skills and digital literacy workshops. Students who have English as a second or other language will be given access to the English for Academic Purposes workshops and resources.', '["1 Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage students"]'::jsonb, 'All students within the ‘Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage’ target groups', '["ethnicity"]'::jsonb, '["attainment"]'::jsonb, '["PTS_1", "PTS_2"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 10 – Cost pressures", "EORR Risk 12 – Progression from higher education"]'::jsonb, 10, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-70603d8de2ab3ae0d38487a1', '10004599', 'Academic Coaches', NULL, 'Train Academic Coaches to support second language speakers of English by funding them to complete attend a part-time CELTA course. New Activity.', '["1 Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage students"]'::jsonb, 'All students within the ‘Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage’ target groups', '["ethnicity"]'::jsonb, '["attainment"]'::jsonb, '["PTS_1", "PTS_2"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 10 – Cost pressures", "EORR Risk 12 – Progression from higher education"]'::jsonb, 11, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-d349289c392c372bebe2f365', '10004599', 'Foundation Programme', NULL, 'Expand curriculum offer to include a foundation year to embed and develop academic support skills in preparation for higher education study. New activity.', '["1 Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage students"]'::jsonb, 'All students within the ‘Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage’ target groups', '["ethnicity"]'::jsonb, '["attainment"]'::jsonb, '["PTS_1", "PTS_2"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 10 – Cost pressures", "EORR Risk 12 – Progression from higher education"]'::jsonb, 11, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-ce49c08b3f07223a05a735ce', '10004599', 'Industry Insights', NULL, 'Employers, entrepreneurs and guest speakers of Asian, black, mixed or other heritages will be invited to speak to students about their own learning and employment journeys. Existing activity. All students within the ‘Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage’ target group will be given access to this intervention.', '["1 Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage students"]'::jsonb, 'All students within the ‘Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage’ target groups', '["ethnicity"]'::jsonb, '["attainment"]'::jsonb, '["PTS_1", "PTS_2"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 10 – Cost pressures", "EORR Risk 12 – Progression from higher education"]'::jsonb, 12, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-dfec3c940cd165ff12078c6b', '10004599', 'Parent and Carer Support', NULL, 'Develop study opportunities and support for students who are parents and/or carers. New activity. All students within the ‘Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage’ target group who are parents and/or carers will be given access to this intervention.', '["1 Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage students"]'::jsonb, 'All students within the ‘Enhanced Support and Access Pathways: Black, Asian, mixed and other heritage’ target group who are parents and/or carers', '["ethnicity", "parents", "carer"]'::jsonb, '["attainment"]'::jsonb, '["PTS_1", "PTS_2"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 10 – Cost pressures", "EORR Risk 12 – Progression from higher education"]'::jsonb, 12, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-87bd1ec5fb8f738bbe0acb68', '10004599', 'Targeted Support Workshops', NULL, 'Delivery of a range of targeted support workshops with dedicated members of the academic and support teams. New activity. There are two strands of this Activity: 1. Workshops focusing on the development of academic skills and mindset. Content is likely to broadly include: •  Academic skills development and practice (e.g. essay writing, referencing, note taking, time management)•  Development of cognitive and metacognitive skills•  Understanding and responding to assessment criteria and expectations•  Locating, evaluating, synthesising and adapting to new forms of knowledge. 2. Workshops focusing on emotional wellbeing and development. Content is likely to include:•  Resilience, perseverance•  Confidence•  Conflict and dispute resolution•  Mindfulness•  Coping strategies•  Mental health awareness and care•  Communication Sessions will be embedded in, co- and extra-curricular. Students, academic specialists, and support staff will collaborate on provision. All students within the ‘Enhanced Support to Address Disadvantage’ target group will be offered this intervention.', '["2 Enhanced Support to Address Disadvantage"]'::jsonb, 'All students within the ‘Enhanced Support to Address Disadvantage’ target group', '["area_based"]'::jsonb, '["attainment"]'::jsonb, '["PTS_3", "PTS_4"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 8 – Mental health", "EORR Risk 10 – Cost pressures"]'::jsonb, 16, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-0f0ce3fe40ec6972a89a0061', '10004599', 'Mentor Scheme', NULL, 'Student mentorship scheme: Level 6 students from deprived areas will mentor target students on Level 4 programmes. New activity. Students within the ‘Enhanced Support to Address Disadvantage’ target group who are studying on a Level 4 programme will be offered this intervention.', '["2 Enhanced Support to Address Disadvantage"]'::jsonb, 'Students within the ‘Enhanced Support to Address Disadvantage’ target group who are studying on a Level 4 programme', '["area_based"]'::jsonb, '["attainment"]'::jsonb, '["PTS_3", "PTS_4"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 8 – Mental health", "EORR Risk 10 – Cost pressures"]'::jsonb, 17, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-77b4c0425dff9e283abf8e48', '10004599', 'Transition Summer School', NULL, 'Summer school transition programme, offering new students the opportunity to meet staff and learn more about their courses and available support. Existing activity. All students within the ‘Enhanced Support to Address Disadvantage’ target group will be offered this intervention.', '["2 Enhanced Support to Address Disadvantage"]'::jsonb, 'All students within the ‘Enhanced Support to Address Disadvantage’ target group', '["area_based"]'::jsonb, '["attainment"]'::jsonb, '["PTS_3", "PTS_4"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 8 – Mental health", "EORR Risk 10 – Cost pressures"]'::jsonb, 18, 'Checked by the automated reviewer; corrections not yet applied'),
  ('qa2-b1a93235f110756c082310da', '10004599', 'Addressing Hardship', NULL, 'Students from deprived areas to be offered subsidised, affordable food; travel support; and, late opening of warm study spaces, giving students space to study away from distraction of personal commitments. New activity. All students within the ‘Enhanced Support to Address Disadvantage’ target group will be offered this intervention.', '["2 Enhanced Support to Address Disadvantage"]'::jsonb, 'All students within the ‘Enhanced Support to Address Disadvantage’ target group', '["area_based"]'::jsonb, '["attainment"]'::jsonb, '["PTS_3", "PTS_4"]'::jsonb, '["EORR Risk 6 – Insufficient academic support", "EORR Risk 7 – Insufficient personal support", "EORR Risk 8 – Mental health", "EORR Risk 10 – Cost pressures"]'::jsonb, 18, 'Checked by the automated reviewer; corrections not yet applied'),
